 bind(){const host=this.host,oldClick=host.onclick,oldInput=host.oninput;host.onclick=e=>{const ex=e.target.closest('[data-layer-expand]'),effect=e.target.closest('[data-layer-effect]'),remove=e.target.closest('[data-layer-remove-effect]'),footer=e.target.closest('[data-layer-action]');if(ex){const id=ex.dataset.layerExpand;this.closed.has(id)?this.closed.delete(id):this.closed.add(id);this.render();return;}const toggle=e.target.closest('[data-layer-toggle-effect]'),lock=e.target.closest('[data-layer-lock-effect]');if(toggle||lock){this.a.toggleEffect((toggle||lock).dataset[toggle?'layerToggleEffect':'layerLockEffect'],!!lock);return;}if(remove){this.a.removeEffect(remove.dataset.layerRemoveEffect);return;}if(effect){this.a.selectEffect(effect.dataset.layerEffect);this.render();return;}if(footer){this.a.action(footer.dataset.layerAction);return;}oldClick(e);};host.oninput=e=>{if(e.target.id==='layer-search'){this.search=e.target.value;const pos=e.target.selectionStart;this.render();const input=host.querySelector('#layer-search');input?.focus();input?.setSelectionRange(pos,pos);}else oldInput(e);};host.ondblclick=e=>{const effect=e.target.closest('[data-layer-effect]');if(effect){this.a.selectEffect(effect.dataset.layerEffect);return;}const row=e.target.closest('[data-layer-id]');if(row&&e.target.closest('.object-icon')){const {p,view}=this.a.state(),o=p.views[view].find(o=>o.id===row.dataset.layerId);if(o?.source||o?.construction){this.a.editConstruction?.(o.id);return;}}const n=e.target.closest('[data-name]');if(!n)return;const {p,view}=this.a.state(),o=p.views[view].find(o=>o.id===n.dataset.name)||p.groups[view].find(g=>g.id===n.dataset.name);if(!o)return;const input=document.createElement('input');input.className='layer-rename';input.value=o.name;input.setAttribute('aria-label','Nombre de capa');n.replaceChildren(input);input.focus();input.select();let finished=false;const finish=save=>{if(finished)return;finished=true;if(save&&input.value.trim())this.a.rename(o.id,input.value.trim());else this.render();};input.onblur=()=>finish(true);input.onkeydown=ev=>{if(ev.key==='Enter'||ev.key==='Escape'){ev.stopPropagation();finish(ev.key==='Enter');}};};const oldDrag=host.ondragstart;host.ondragstart=e=>{if(e.target.closest('[data-resource]'))return oldDrag(e);const row=e.target.closest('[data-layer-id]');if(!row||row.dataset.layerEffect){e.preventDefault();return;}if(!interactions.begin('layers','LAYER_DRAG',null,()=>this.endDrag())){e.preventDefault();return;}const {p,view,selected}=this.a.state(),id=row.dataset.layerId,logicalSelected=[...new Set(selected.map(id=>logicalLayerId(p,view,id)))];this.scrollTimer=setInterval(()=>{if(this.scrollDelta)(this.host.querySelector('.layer-tree')||this.host).scrollTop+=this.scrollDelta;},30);this.activeDrag={ids:row.dataset.group?[id]:logicalSelected.includes(id)?logicalSelected:[id],row};row.classList.add('layer-dragging');e.dataTransfer.setData('application/siluetra-layers',JSON.stringify(this.activeDrag.ids));e.dataTransfer.effectAllowed='move';if(row.cloneNode&&document.body){const ghost=row.cloneNode(true);ghost.classList.add('layer-drag-ghost');const badge=document.createElement('span');badge.className='layer-drag-count';badge.textContent=this.activeDrag.ids.length+' capas';ghost.appendChild(badge);document.body.appendChild(ghost);e.dataTransfer.setDragImage?.(ghost,20,15);setTimeout(()=>ghost.remove(),0);}};host.ondragover=e=>{if(!this.activeDrag)return;e.preventDefault();const row=e.target.closest('[data-layer-id]');if(!row)return;const r=row.getBoundingClientRect(),fraction=(e.clientY-r.top)/r.height,position=row.dataset.group&&fraction>.25&&fraction<.75?'inside':fraction<.5?'above':'below',id=row.dataset.layerId,{p,view}=this.a.state(),valid=validLayerDrop(p,view,this.activeDrag.ids,id,position);for(const el of host.querySelectorAll('[data-drop-position]'))delete el.dataset.dropPosition;row.dataset.dropPosition=valid?position:'forbidden';const allRows=[...host.querySelectorAll('[data-layer-id]')],at=allRows.indexOf(row);allRows.forEach((el,i)=>el.style.transform=valid&&position!=='inside'&&(position==='above'?i>=at:i>at)?'translateY(8px)':'');e.dataTransfer.dropEffect=valid?'move':'none';this.activeDrag.target=id;this.activeDrag.position=position;const hr=host.getBoundingClientRect();this.scrollDelta=e.clientY<hr.top+45?-14:e.clientY>hr.bottom-45?14:0;if(position==='inside'&&this.closed.has(id)){if(this.hoverId!==id){clearTimeout(this.hoverTimer);this.hoverId=id;this.hoverTimer=setTimeout(()=>{this.closed.delete(id);this.render();},750);}}else{clearTimeout(this.hoverTimer);this.hoverId=null;}};host.ondrop=e=>{if(!this.activeDrag)return;e.preventDefault();const {ids,target,position}=this.activeDrag,{p,view}=this.a.state();try{if(validLayerDrop(p,view,ids,target,position)){const positions=new Map([...host.querySelectorAll('[data-layer-id]')].map(el=>[el.dataset.layerId,el.getBoundingClientRect().top]));this.a.commit(()=>moveLayers(p,view,ids,target,position),'Reordenar capas');for(const el of host.querySelectorAll('[data-layer-id]')){const before=positions.get(el.dataset.layerId);if(before!==undefined)el.animate?.([{transform:`translateY(${before-el.getBoundingClientRect().top}px)`},{transform:'translateY(0)'}],{duration:150,easing:'ease-out'});}}}finally{this.endDrag();}};host.ondragend=()=>this.endDrag();}
